1	import { readFile } from "node:fs/promises";
2	import { setTimeout as sleep } from "node:timers/promises";
3	
4	// Reads a recorded stream-json file and splits it into runs.
5	export async function readRuns(file: string): Promise<string[][]> {
6	  const text = await readFile(file, "utf8");
7	  return splitRuns(text.split("\n").filter((line) => line.trim()));
8	}
9	
10	// Every run opens with a system/init event (a resumed or auto-continued run prints a fresh one),
11	// so a new run starts at each init; anything before the first init belongs to the first run.
12	export function splitRuns(lines: string[]): string[][] {
13	  const runs: string[][] = [];
14	  let current: string[] = [];
15	  for (const line of lines) {
16	    if (isInit(line) && current.length > 0) {
17	      runs.push(current);
18	      current = [];
19	    }
20	    current.push(line);
21	  }
22	  if (current.length > 0) runs.push(current);
23	  return runs;
24	}
25	
26	function isInit(line: string): boolean {
27	  try {
28	    const event = JSON.parse(line);
29	    return event.type === "system" && event.subtype === "init";
30	  } catch {
31	    return false;
32	  }
33	}
34	
35	// Yields lines with a pause between them, so the page sees events arrive one by one the way a live run delivers them.
36	export async function* replayLines(lines: string[], delayMs: number, signal: AbortSignal) {
37	  for (const line of lines) {
38	    if (signal.aborted) return;
39	    yield line;
40	    await sleep(delayMs, undefined, { signal }).catch(() => {});
41	  }
42	}
