1	import { useEffect, useLayoutEffect, useReducer, useRef, useState } from "react";
2	import { TextBlock } from "./components/TextBlock.tsx";
3	import { ToolCall } from "./components/ToolCall.tsx";
4	import { readNdjson } from "./ndjson.ts";
5	import { emptyTrajectory, reducer, type Run, type RunStats, type RunStatus } from "./trajectory.ts";
6	
7	type Status =
8	  | { kind: "idle" }
9	  | { kind: "streaming"; run: number }
10	  | { kind: "done"; run: number }
11	  | { kind: "error"; run: number; message: string };
12	
13	interface Fixture {
14	  name: string;
15	  runs: number;
16	}
17	
18	export function App() {
19	  const [trajectory, dispatch] = useReducer(reducer, emptyTrajectory);
20	  const [status, setStatus] = useState<Status>({ kind: "idle" });
21	  const [fixtures, setFixtures] = useState<Fixture[]>([]);
22	  const [fixture, setFixture] = useState("trace.jsonl");
23	  // The run the button plays next (1-based). Back at 1 once every run of the fixture has been played.
24	  const [nextRun, setNextRun] = useState(1);
25	  const totalRuns = fixtures.find((f) => f.name === fixture)?.runs ?? 1;
26	  const nearBottom = useNearBottom();
27	
28	  useEffect(() => {
29	    fetch("/api/fixtures")
30	      .then((res) => res.json())
31	      .then(setFixtures)
32	      .catch(() => setFixtures([]));
33	  }, []);
34	
35	  // Follow new events only while the reader is already at the bottom, so scrolling up to read is not interrupted.
36	  useLayoutEffect(() => {
37	    if (nearBottom.current) window.scrollTo({ top: document.documentElement.scrollHeight });
38	  }, [trajectory, nearBottom]);
39	
40	  function chooseFixture(name: string) {
41	    setFixture(name);
42	    setNextRun(1);
43	    setStatus({ kind: "idle" });
44	    dispatch({ type: "reset" });
45	  }
46	
47	  // Plays one run per click. Run 1 starts a fresh trajectory; later runs are appended below it,
48	  // the way a follow-up prompt continues the same session.
49	  async function replay() {
50	    const run = nextRun;
51	    if (run === 1) dispatch({ type: "reset" });
52	    setStatus({ kind: "streaming", run });
53	    try {
54	      const res = await fetch(`/api/replay?file=${encodeURIComponent(fixture)}&run=${run}`);
55	      if (!res.ok || !res.body) throw new Error(`replay request failed (HTTP ${res.status})`);
56	      for await (const event of readNdjson(res.body)) dispatch({ type: "event", event });
57	      dispatch({ type: "end" });
58	      setStatus({ kind: "done", run });
59	    } catch (err) {
60	      const message = err instanceof Error ? err.message : String(err);
61	      dispatch({ type: "end", error: message });
62	      setStatus({ kind: "error", run, message });
63	    }
64	    setNextRun(run >= totalRuns ? 1 : run + 1);
65	  }
66	
67	  const streaming = status.kind === "streaming";
68	  return (
69	    <div className="page">
70	      <header className="header">
71	        <div>
72	          <h1>Claude Code Trajectory</h1>
73	          <p className="subtitle">Replaying a recorded stream-json run, event by event.</p>
74	        </div>
75	        <div className="controls">
76	          <StatusText status={status} totalRuns={totalRuns} />
77	          <select className="fixture-select" value={fixture} onChange={(e) => chooseFixture(e.target.value)} disabled={streaming}>
78	            {(fixtures.length > 0 ? fixtures.map((f) => f.name) : [fixture]).map((name) => (
79	              <option key={name} value={name}>
80	                {name}
81	              </option>
82	            ))}
83	          </select>
84	          <button className="primary" onClick={replay} disabled={streaming}>
85	            {nextRun === 1 ? "Replay" : `Continue · run ${nextRun}/${totalRuns}`}
86	          </button>
87	        </div>
88	      </header>
89	
90	      <main className="runs">
91	        {trajectory.runs.length === 0 ? (
92	          <div className="card">
93	            <p className="empty">Pick a recorded run and press Replay to stream it into the page.</p>
94	          </div>
95	        ) : (
96	          trajectory.runs.map((run) => <RunView key={run.index} run={run} />)
97	        )}
98	        {!streaming && nextRun > 1 && trajectory.runs.length > 0 && (
99	          <button className="next-run" onClick={replay}>
100	            <span className="next-run-title">▶ Next run ({nextRun}/{totalRuns})</span>
101	            <span className="next-run-hint">Click to replay the next run of this session</span>
102	          </button>
103	        )}
104	      </main>
105	    </div>
106	  );
107	}
108	
109	function RunView({ run }: { run: Run }) {
110	  const ended = run.status !== "running";
111	  return (
112	    <section className="run card">
113	      <div className="run-divider">
114	        <span>Run {run.index}</span>
115	        <SessionLabel run={run} />
116	        {run.model && <span className="mono">{run.model}</span>}
117	        <span className="run-line" />
118	        <RunStatusBadge status={run.status} />
119	      </div>
120	      {run.items.map((item) =>
121	        item.kind === "text" ? (
122	          <TextBlock key={item.key} text={item.text} />
123	        ) : (
124	          <ToolCall key={item.key} item={item} cwd={run.cwd} runEnded={ended} />
125	        ),
126	      )}
127	      {run.failure && (
128	        <div className="run-error">
129	          <strong>{run.failure.kind}</strong>
130	          {run.failure.message !== run.failure.kind && <span>{run.failure.message}</span>}
131	        </div>
132	      )}
133	      {run.stats && <RunStatsLine stats={run.stats} sessionId={run.sessionId} />}
134	    </section>
135	  );
136	}
137	
138	// The run's numbers from its result event: cost, wall-clock duration, and model turns.
139	function RunStatsLine({ stats, sessionId }: { stats: RunStats; sessionId: string }) {
140	  const session = `$${formatCost(stats.sessionCostUsd)}`;
141	  const parts = [
142	    stats.runCostUsd !== undefined ? `$${formatCost(stats.runCostUsd)}` : `session total ${session}`,
143	    formatDuration(stats.durationMs),
144	    stats.numTurns === 1 ? "1 turn" : `${stats.numTurns} turns`,
145	  ];
146	  if (sessionId) parts.push(`session ${sessionId.slice(0, 8)}…`);
147	  return (
148	    <div className="run-stats">
149	      <span>{parts.join(" · ")}</span>
150	      {stats.runCostUsd !== undefined && <span className="run-stats-total">(session total {session})</span>}
151	    </div>
152	  );
153	}
154	
155	function formatCost(usd: number): string {
156	  return usd < 1 ? usd.toFixed(4) : usd.toFixed(2);
157	}
158	
159	function formatDuration(ms: number): string {
160	  const seconds = ms / 1000;
161	  if (seconds < 60) return `${seconds.toFixed(1)} s`;
162	  return `${Math.floor(seconds / 60)} m ${Math.round(seconds % 60)} s`;
163	}
164	
165	// A run that shares its session id with an earlier one continues that conversation. Usually that is a resumed
166	// follow-up prompt, but the harness can also start a run itself when a background task finishes.
167	function SessionLabel({ run }: { run: Run }) {
168	  if (!run.sessionId) return null;
169	  const session = `${run.sessionId.slice(0, 8)}…`;
170	  if (!run.resumed) return <span className="mono">session {session}</span>;
171	  if (run.origin === "task-notification") {
172	    return <span className="resumed">↻ auto-continued · background task notification</span>;
173	  }
174	  return <span className="resumed">↻ resumed session {session}</span>;
175	}
176	
177	function RunStatusBadge({ status }: { status: RunStatus }) {
178	  switch (status) {
179	    case "running":
180	      return (
181	        <span className="run-status run-status-running">
182	          <span className="dot" /> running
183	        </span>
184	      );
185	    case "finished":
186	      return <span className="run-status run-status-finished">✓ finished</span>;
187	    case "failed":
188	      return <span className="run-status run-status-failed">✕ failed</span>;
189	  }
190	}
191	
192	function StatusText({ status, totalRuns }: { status: Status; totalRuns: number }) {
193	  switch (status.kind) {
194	    case "idle":
195	      return totalRuns > 1 ? <span className="status">{totalRuns} runs recorded</span> : null;
196	    case "streaming":
197	      return (
198	        <span className="status status-live">
199	          <span className="dot" /> streaming run {status.run}/{totalRuns}…
200	        </span>
201	      );
202	    case "done": {
203	      const left = totalRuns - status.run;
204	      if (left > 0) return <span className="status">{left === 1 ? "1 run left" : `${left} runs left`}</span>;
205	      return <span className="status">{totalRuns === 1 ? "run replayed" : `all ${totalRuns} runs replayed`}</span>;
206	    }
207	    case "error":
208	      return <span className="status status-error">{status.message}</span>;
209	  }
210	}
211	
212	function useNearBottom() {
213	  const near = useRef(true);
214	  useEffect(() => {
215	    const update = () => {
216	      near.current = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 80;
217	    };
218	    window.addEventListener("scroll", update, { passive: true });
219	    return () => window.removeEventListener("scroll", update);
220	  }, []);
221	  return near;
222	}
