1	import type { StreamEvent } from "./events.ts";
2	
3	// Reads a newline-delimited JSON response body and yields each event as soon as its line is complete.
4	export async function* readNdjson(body: ReadableStream<Uint8Array>): AsyncGenerator<StreamEvent> {
5	  const reader = body.getReader();
6	  const decoder = new TextDecoder();
7	  let buffered = "";
8	  while (true) {
9	    const { value, done } = await reader.read();
10	    if (done) break;
11	    buffered += decoder.decode(value, { stream: true });
12	    const lines = buffered.split("\n");
13	    buffered = lines.pop() ?? "";
14	    for (const line of lines) {
15	      const event = parseLine(line);
16	      if (event) yield event;
17	    }
18	  }
19	  const event = parseLine(buffered);
20	  if (event) yield event;
21	}
22	
23	function parseLine(line: string): StreamEvent | null {
24	  if (!line.trim()) return null;
25	  try {
26	    return JSON.parse(line) as StreamEvent;
27	  } catch {
28	    console.warn("skipping malformed stream line:", line.slice(0, 200));
29	    return null;
30	  }
31	}
