1	// The subset of Claude Code's stream-json events the page reads.
2	// Anything not listed here is passed through and ignored by the reducer.
3	
4	export interface TextContent {
5	  type: "text";
6	  text: string;
7	}
8	
9	export interface ToolUseContent {
10	  type: "tool_use";
11	  id: string;
12	  name: string;
13	  input: Record<string, unknown>;
14	}
15	
16	export type ContentBlock = TextContent | ToolUseContent | { type: "thinking" | "redacted_thinking" };
17	
18	export interface InitEvent {
19	  type: "system";
20	  subtype: "init";
21	  session_id: string;
22	  cwd: string;
23	  model: string;
24	}
25	
26	export interface AssistantEvent {
27	  type: "assistant";
28	  message: { id: string; content: ContentBlock[] };
29	  // The tool call (an Agent/Task call) that spawned the subagent emitting this event; null for the main agent.
30	  parent_tool_use_id: string | null;
31	}
32	
33	// What the model is shown after a tool runs. content is either plain text or a list of blocks
34	// (text, images, or tool_reference entries naming tools that ToolSearch loaded).
35	export interface ToolResultContent {
36	  type: "tool_result";
37	  tool_use_id: string;
38	  content?: string | { type: string; text?: string; tool_name?: string }[];
39	  is_error?: boolean;
40	}
41	
42	export interface UserEvent {
43	  type: "user";
44	  message: { content: string | (ToolResultContent | { type: "text"; text: string })[] };
45	  parent_tool_use_id: string | null;
46	}
47	
48	// Printed once when a run ends. is_error marks a failed run (e.g. subtype "error_max_turns").
49	export interface ResultEvent {
50	  type: "result";
51	  subtype: string;
52	  is_error: boolean;
53	  errors?: string[];
54	  // Cumulative across the whole session: a resumed run continues the total of the runs before it.
55	  total_cost_usd: number;
56	  // Wall-clock time and model calls of this run only.
57	  duration_ms: number;
58	  num_turns: number;
59	  // Set when the harness started this run itself, e.g. { kind: "task-notification" } after a background task finished.
60	  origin?: { kind: string } | null;
61	}
62	
63	export interface OtherEvent {
64	  type: string;
65	  subtype?: string;
66	}
67	
68	export type StreamEvent = InitEvent | AssistantEvent | UserEvent | ResultEvent | OtherEvent;
69	
70	export function isInit(ev: StreamEvent): ev is InitEvent {
71	  return ev.type === "system" && ev.subtype === "init";
72	}
73	
74	export function isAssistant(ev: StreamEvent): ev is AssistantEvent {
75	  return ev.type === "assistant";
76	}
77	
78	export function isUser(ev: StreamEvent): ev is UserEvent {
79	  return ev.type === "user";
80	}
81	
82	export function isResult(ev: StreamEvent): ev is ResultEvent {
83	  return ev.type === "result";
84	}
