1	import { isAssistant, isInit, isResult, isUser, type StreamEvent, type ToolResultContent } from "./events.ts";
2	
3	export interface TextItem {
4	  kind: "text";
5	  key: string;
6	  text: string;
7	  parentId: string | null;
8	}
9	
10	export interface ToolItem {
11	  kind: "tool";
12	  key: string;
13	  id: string;
14	  name: string;
15	  input: Record<string, unknown>;
16	  parentId: string | null;
17	  result?: ToolResult;
18	}
19	
20	export interface ToolResult {
21	  text: string;
22	  isError: boolean;
23	}
24	
25	export type Item = TextItem | ToolItem;
26	
27	export type RunStatus = "running" | "finished" | "failed";
28	
29	export interface Run {
30	  index: number;
31	  sessionId: string;
32	  model: string;
33	  cwd: string;
34	  items: Item[];
35	  status: RunStatus;
36	  failure?: { kind: string; message: string };
37	  // True when an earlier run had the same session id, i.e. this run continues that conversation.
38	  resumed: boolean;
39	  // Who started the run when it was not a prompt, from result.origin (e.g. "task-notification").
40	  origin?: string;
41	  stats?: RunStats;
42	}
43	
44	export interface RunStats {
45	  // This run's own cost; undefined when the previous run of a resumed session is not in view.
46	  runCostUsd?: number;
47	  sessionCostUsd: number;
48	  durationMs: number;
49	  numTurns: number;
50	}
51	
52	export interface Trajectory {
53	  runs: Run[];
54	  eventCount: number;
55	}
56	
57	export const emptyTrajectory: Trajectory = { runs: [], eventCount: 0 };
58	
59	// "end" is dispatched when the event stream closes, with an error if the request itself failed.
60	export type Action = { type: "reset" } | { type: "event"; event: StreamEvent } | { type: "end"; error?: string };
61	
62	export function reducer(state: Trajectory, action: Action): Trajectory {
63	  if (action.type === "reset") return emptyTrajectory;
64	  if (action.type === "end") return endStream(state, action.error);
65	  return applyEvent(state, action.event);
66	}
67	
68	function newRun(index: number, fields: Partial<Run> = {}): Run {
69	  return { index, sessionId: "", model: "", cwd: "", items: [], status: "running", resumed: false, ...fields };
70	}
71	
72	// A run that is still running when the stream closes never got its result event, so it failed.
73	// If nothing arrived at all, a placeholder run carries the failure so it is still visible.
74	function endStream(state: Trajectory, error?: string): Trajectory {
75	  const failure = error
76	    ? { kind: "request failed", message: error }
77	    : { kind: "stream ended", message: "The event stream ended before the run's result event arrived." };
78	  if (state.runs.length === 0) return { ...state, runs: [newRun(1, { status: "failed", failure })] };
79	  const runs = state.runs.map((run) => (run.status === "running" ? { ...run, status: "failed" as const, failure } : run));
80	  return { ...state, runs };
81	}
82	
83	function applyEvent(state: Trajectory, ev: StreamEvent): Trajectory {
84	  const eventCount = state.eventCount + 1;
85	
86	  // Each init event starts a new run (a resumed session prints a fresh init).
87	  if (isInit(ev)) {
88	    const resumed = state.runs.some((r) => r.sessionId === ev.session_id);
89	    const run = newRun(state.runs.length + 1, { sessionId: ev.session_id, model: ev.model, cwd: ev.cwd, resumed });
90	    return { runs: [...state.runs, run], eventCount };
91	  }
92	
93	  // The result event closes the current run: is_error decides finished vs failed.
94	  if (isResult(ev) && state.runs.length > 0) {
95	    const current = state.runs[state.runs.length - 1];
96	    const stats: RunStats = {
97	      runCostUsd: runCost(state.runs.slice(0, -1), current, ev.total_cost_usd),
98	      sessionCostUsd: ev.total_cost_usd,
99	      durationMs: ev.duration_ms,
100	      numTurns: ev.num_turns,
101	    };
102	    const last = { ...current, origin: ev.origin?.kind, stats };
103	    const ended: Run = ev.is_error
104	      ? { ...last, status: "failed", failure: { kind: ev.subtype, message: ev.errors?.join("\n") || ev.subtype } }
105	      : { ...last, status: "finished" };
106	    return { runs: [...state.runs.slice(0, -1), ended], eventCount };
107	  }
108	
109	  // Assistant events carry one content block each; text and tool_use become items, thinking is skipped.
110	  // Partial-message stream_events are ignored because the complete assistant event always follows them.
111	  if (isAssistant(ev)) {
